fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let r: i32 = if w < h { w / 2 - 10 } else { h / 2 - 10 };
    host::display::clear(0x000000);
    let mut k: i32 = 0;
    while k < 16 {
        let tx: i32 = cx + tab[k * 2] * r / 127;
        let ty: i32 = cy + tab[(k * 2 + 8) & 31] * r / 127;
        host::display::fill_rect(tx - 1, ty - 1, 2, 2, 0x104010);
        k = k + 1;
    }
    let a: i32 = (t / 2) & 31;
    let mut trail: i32 = 2;
    while trail >= 0 {
        let idx: i32 = (a - trail + 32) & 31;
        let ex: i32 = cx + tab[idx] * r / 127;
        let ey: i32 = cy + tab[(idx + 8) & 31] * r / 127;
        let c: i32 = if trail == 0 { 0x40ff40 } else if trail == 1 { 0x208020 } else { 0x104010 };
        host::display::draw_line(cx, cy, ex, ey, c);
        trail = trail - 1;
    }
    let bearing: i32 = 5;
    let bx: i32 = cx + tab[bearing] * r * 2 / 3 / 127;
    let by: i32 = cy + tab[(bearing + 8) & 31] * r * 2 / 3 / 127;
    if ((a - bearing + 32) & 31) < 6 {
        host::display::fill_rect(bx - 2, by - 2, 4, 4, 0x80ff80);
    }
    host::display::present();
}
